 // --- Configuration ---
 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable to run this agent.");

 var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

 // --- Build IChatClient via MEAI abstraction ---
 IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
     .GetChatClient(modelId)
     .AsIChatClient();

 // --- Shared state for note-taking tool ---
 var notes = new List<string>();

 // --- Define tools ---
 var tools = new AITool[]
 {
     AIFunctionFactory.Create(WebSearch),
     AIFunctionFactory.Create(SaveNote),
     AIFunctionFactory.Create(GetNotes),
 };

 // --- Create the research agent using Microsoft Agent Framework ---
 var researchAgent = new ChatClientAgent(
     chatClient,
     instructions: """
         You are a research agent. When given a topic, you:
         1. Search the web for relevant information (perform multiple searches to cover different angles).
         2. Save important findings as notes.
         3. After gathering enough information, retrieve your notes and produce a comprehensive summary.
         Always cite your sources. Be thorough but concise.
         """,
     name: "ResearchAgent",
     description: "An agent that researches topics by searching the web and summarizing findings.",
     tools: tools);

 // --- Run the agent ---
 var topic = args.Length > 0
     ? string.Join(' ', args)
     : "recent advances in quantum computing 2025";

 Console.WriteLine($"🔍 Researching: {topic}\n");

 var session = await researchAgent.CreateSessionAsync();
 var response = await researchAgent.RunAsync(
     $"Research the following topic and provide a comprehensive summary: {topic}",
     session,
     new ChatClientAgentRunOptions
     {
         ChatOptions = new ChatOptions
         {
             Temperature = 0f,
             MaxOutputTokens = 2048,
         },
     });

 Console.WriteLine("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
 Console.WriteLine("📋 Research Summary");
 Console.WriteLine("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
 Console.WriteLine(response.Text);
 Console.WriteLine("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");

 if (response.Usage is { } usage)
 {
     Console.WriteLine($"\n📊 Tokens — Input: {usage.InputTokenCount}, Output: {usage.OutputTokenCount}");
 }

 // --- Tool implementations ---

 [Description("Search the web for information on a given query. Returns a list of relevant results with titles, snippets, and URLs.")]
 static string WebSearch([Description("The search query")] string query)
 {
     // Simulated web search results for demonstration purposes.
     // In production, replace with a real search API (e.g., Bing Search, Google Custom Search).
     Console.WriteLine($"  🌐 Searching: \"{query}\"");

     return $$"""
         Search results for "{{query}}":

         1. Title: "{{query}} - Latest Developments"
            URL: https://example.com/article1
            Snippet: Recent breakthroughs in {{query}} have shown promising results across multiple research institutions worldwide.

         2. Title: "Understanding {{query}}: A 2025 Overview"
            URL: https://example.com/article2
            Snippet: Experts predict significant progress in {{query}} over the next decade, with practical applications emerging in various industries.

         3. Title: "{{query}} Research Roundup"
            URL: https://example.com/article3
            Snippet: Key researchers have published new findings demonstrating novel approaches to {{query}} that could transform the field.
         """;
 }

 [Description("Save an important finding or note for later reference during research.")]
 string SaveNote([Description("The note content to save")] string note)
 {
     notes.Add(note);
     Console.WriteLine($"  📝 Note saved ({notes.Count} total)");
     return $"Note saved successfully. You now have {notes.Count} note(s).";
 }

 [Description("Retrieve all saved notes to use when writing the final summary.")]
 string GetNotes()
 {
     if (notes.Count == 0)
     {
         return "No notes saved yet.";
     }

     Console.WriteLine($"  📖 Retrieving {notes.Count} note(s)");
     return string.Join("\n\n---\n\n", notes.Select((n, i) => $"Note {i + 1}: {n}"));
 }
